{
  "Comment": "Monolith Identifier V2 - Complete workflow for monolithic pattern detection and decomposition strategy generation",
  "StartAt": "UpdateStatusRunning",
  "States": {
    "UpdateStatusRunning": {
      "Type": "Task",
      "Resource": "arn:aws:states:::aws-sdk:s3:putObject",
      "Parameters": {
        "Bucket": "code-transformation-v2",
        "Key.$": "States.Format('{}/{}/monolith_identifier_v2/jobs/{}/status.json', $.scout_account_id, $.application_name, $.job_id)",
        "Body": "{\"state\": \"running\", \"status\": \"running\", \"progress\": 5, \"phase\": \"starting\", \"message\": \"Monolith analysis workflow started\"}",
        "ContentType": "application/json"
      },
      "ResultPath": null,
      "Next": "PrepareAnalysis"
    },

    "PrepareAnalysis": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:376129851858:function:MonolithIdentifierV2PrepareAnalysis",
      "ResultPath": "$.prepare_result",
      "Next": "StaticAnalysisMap"
    },

    "StaticAnalysisMap": {
      "Type": "Map",
      "ItemsPath": "$.prepare_result.batches",
      "ItemProcessor": {
        "ProcessorConfig": {
          "Mode": "DISTRIBUTED",
          "ExecutionType": "STANDARD"
        },
        "StartAt": "StaticParser",
        "States": {
          "StaticParser": {
            "Type": "Task",
            "Resource": "arn:aws:lambda:us-east-1:376129851858:function:MonolithIdentifierV2StaticParser",
            "End": true
          }
        }
      },
      "MaxConcurrency": 40,
      "Label": "StaticAnalysisMap",
      "ResultPath": "$.static_batches",
      "Next": "MergeStatic"
    },

    "MergeStatic": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:376129851858:function:MonolithIdentifierV2MergeStatic",
      "Parameters": {
        "job_id.$": "$.job_id",
        "scout_account_id.$": "$.scout_account_id",
        "application_name.$": "$.application_name",
        "total_batches.$": "$.prepare_result.total_batches"
      },
      "ResultPath": "$.merge_result",
      "Next": "AIAnalyzer"
    },

    "AIAnalyzer": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:376129851858:function:MonolithIdentifierV2AIAnalyzer",
      "Parameters": {
        "job_id.$": "$.job_id",
        "scout_account_id.$": "$.scout_account_id",
        "application_name.$": "$.application_name"
      },
      "ResultPath": "$.ai_result",
      "Next": "ModularityCalculator",
      "TimeoutSeconds": 300,
      "Retry": [
        {
          "ErrorEquals": ["States.ALL"],
          "IntervalSeconds": 2,
          "MaxAttempts": 2,
          "BackoffRate": 2.0
        }
      ]
    },

    "ModularityCalculator": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:376129851858:function:MonolithIdentifierV2ModularityCalculator",
      "Parameters": {
        "job_id.$": "$.job_id",
        "scout_account_id.$": "$.scout_account_id",
        "application_name.$": "$.application_name"
      },
      "ResultPath": "$.modularity_result",
      "Next": "PatternDetector"
    },

    "PatternDetector": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:376129851858:function:MonolithIdentifierV2PatternDetector",
      "Parameters": {
        "job_id.$": "$.job_id",
        "scout_account_id.$": "$.scout_account_id",
        "application_name.$": "$.application_name"
      },
      "ResultPath": "$.patterns_result",
      "Next": "DecompositionStrategy"
    },

    "DecompositionStrategy": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:376129851858:function:MonolithIdentifierV2DecompositionStrategy",
      "Parameters": {
        "job_id.$": "$.job_id",
        "scout_account_id.$": "$.scout_account_id",
        "application_name.$": "$.application_name"
      },
      "ResultPath": "$.decomposition_result",
      "Next": "UpdateStatusCompleted"
    },

    "UpdateStatusCompleted": {
      "Type": "Task",
      "Resource": "arn:aws:states:::aws-sdk:s3:putObject",
      "Parameters": {
        "Bucket": "code-transformation-v2",
        "Key.$": "States.Format('{}/{}/monolith_identifier_v2/jobs/{}/status.json', $.scout_account_id, $.application_name, $.job_id)",
        "Body": "{\"state\": \"completed\", \"status\": \"completed\", \"progress\": 100, \"phase\": \"completed\", \"message\": \"Monolith analysis completed successfully\"}",
        "ContentType": "application/json"
      },
      "ResultPath": null,
      "Next": "Success"
    },

    "Success": {
      "Type": "Succeed"
    }
  }
}
